// Compile Paraglide messages before Vite/Nitro load `src/server.ts`.
//
// `src/paraglide/` is gitignored and generated by paraglideVitePlugin, but
// Nitro statically imports `./paraglide/server.js` at startup — before the
// Vite plugin has written files. Fresh clones therefore fail `pnpm dev`.
//
// Options must stay in sync with `paraglideVitePlugin({...})` in vite.config.ts.
// The CLI supports --project / --outdir / --output-structure / --strategy, but
// not urlPatterns or cookieName — so we call compile() programmatically.
import { compile } from "@inlang/paraglide-js";

await compile({
  project: "./project.inlang",
  outdir: "./src/paraglide",
  outputStructure: "message-modules",
  cookieName: "PARAGLIDE_LOCALE",
  strategy: ["url", "cookie", "baseLocale"],
  urlPatterns: [
    {
      pattern: "/api/:path(.*)?",
      localized: [
        ["en", "/api/:path(.*)?"],
        ["zh", "/api/:path(.*)?"],
      ],
    },
    {
      pattern: "/",
      localized: [
        ["zh", "/zh"],
        ["en", "/"],
      ],
    },
    {
      pattern: "/:path(.*)?",
      localized: [
        ["zh", "/zh/:path(.*)?"],
        ["en", "/:path(.*)?"],
      ],
    },
  ],
});
